import { useEffect, useState } from "react";
import { fetchInsights } from "../services/api.js";
import SectorIntensityChart from "./charts/SectorIntensityChart.js";

function Dashboard() {
  const [data, setData] = useState([]);

  useEffect(() => {
    fetchInsights().then(setData);
  }, []);

  return (
    <div className="p-6">
      <h1 className="text-2xl font-bold mb-4">📊 Insights Dashboard</h1>
      <SectorIntensityChart data={data} />
    </div>
  );
}

export default Dashboard;
